sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float cellSize;
uniform float jitter;
uniform float mode;
uniform float edgeWidth;
uniform float speed;
layout(color) uniform half4 colorA;
layout(color) uniform half4 colorB;
uniform float blend;
uniform float amount;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float2 hash22(float2 p) {
    return float2(hash21(p), hash21(p + float2(17.31, 5.17)));
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 p = coord / max(cellSize, 1.0);
    float2 ip = floor(p);
    float2 fp = fract(p);
    float d1 = 8.0;
    float d2 = 8.0;
    float2 id1 = float2(0.0);
    for (int j = 0; j < 3; j++) {
        for (int i = 0; i < 3; i++) {
            float2 g = float2(float(i) - 1.0, float(j) - 1.0);
            float2 o = hash22(ip + g);
            o = 0.5 + 0.5 * sin(time * speed + 6.2831853 * o);
            o = mix(float2(0.5), o, jitter);
            float2 r = g + o - fp;
            float d = dot(r, r);
            if (d < d1) {
                d2 = d1;
                d1 = d;
                id1 = ip + g;
            } else if (d < d2) {
                d2 = d;
            }
        }
    }
    float edge = sqrt(d2) - sqrt(d1);
    float3 layer = mix(float3(colorA.rgb), float3(colorB.rgb), hash21(id1));
    if (mode > 0.5 && mode < 1.5) layer = unp(tex((id1 + 0.5) * cellSize));
    else if (mode > 1.5 && mode < 2.5) layer = mix(float3(colorB.rgb), float3(colorA.rgb), smoothstep(0.0, edgeWidth, edge));
    else if (mode > 2.5) layer = mix(float3(colorA.rgb), float3(colorB.rgb), saturate(sqrt(d1)));
    float3 o = mix(s, blendm(s, layer, blend), amount);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), 1.0);
}
